-- Seasonal events and national holidays (generated by db/events/build-migration.mjs).

-- Halloween: Haunted Latvia
INSERT INTO collections (slug, title, description, icon, kind, country, xp_reward, starts_at, ends_at, status, sort, i18n)
VALUES ('halloween-2026', 'Halloween: Haunted Latvia', 'Castle ruins, fortresses and ghost legends. Limited edition until 2 November.', '', 'seasonal', 'LV', 600, '2026-10-24 00:00 Europe/Riga'::timestamptz, '2026-11-03 00:00 Europe/Riga'::timestamptz, 'published', 2,
        '{"lv":{"title":"Helovīni: spoku Latvija","description":"Pilsdrupas, cietokšņi un spoku leģendas. Ierobežots laiks: līdz 2. novembrim."},"ru":{"title":"Хэллоуин: Латвия с привидениями","description":"Руины замков, крепости и легенды о призраках. Только до 2 ноября."}}'::jsonb)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO challenges (slug, title, description, type, category_id, place_id, country, region_id, difficulty, xp_reward,
                        verification, starts_at, ends_at, status, i18n)
SELECT 'halloween-2026-koknese-castle', 'Halloween: ' || p.name, 'Visit this spooky spot during Halloween week.' || ' ' || p.description || ' Get within ' || p.radius_m || ' m to complete.',
       'seasonal', p.category_id, p.id, p.country, p.region_id, 'casual', 150, 'gps', '2026-10-24 00:00 Europe/Riga'::timestamptz, '2026-11-03 00:00 Europe/Riga'::timestamptz, 'published',
       jsonb_build_object(
         'lv', jsonb_build_object('title', 'Helovīni: ' || coalesce(p.i18n->'lv'->>'name', p.name),
               'description', 'Apmeklē šo baiso vietu Helovīnu nedēļā.' || ' ' || coalesce(p.i18n->'lv'->>'description', p.description) || ' Pietuvojies ' || p.radius_m || ' m attālumā, lai izpildītu.'),
         'ru', jsonb_build_object('title', 'Хэллоуин: ' || coalesce(p.i18n->'ru'->>'name', p.name),
               'description', 'Посетите это жуткое место во время недели Хэллоуина.' || ' ' || coalesce(p.i18n->'ru'->>'description', p.description) || ' Подойдите ближе чем на ' || p.radius_m || ' м, чтобы выполнить.'))
FROM places p WHERE p.slug = 'koknese-castle'
ON CONFLICT (slug) DO NOTHING;
INSERT INTO collection_items (collection_id, challenge_id, position)
SELECT c.id, ch.id, 1 FROM collections c, challenges ch WHERE c.slug = 'halloween-2026' AND ch.slug = 'halloween-2026-koknese-castle'
ON CONFLICT DO NOTHING;
