SELECT 'summer-2027-jurmala-beach', 'Summer: ' || p.name, 'Visit in summer.' || ' ' || p.description || ' Get within ' || p.radius_m || ' m to complete.',
       'seasonal', p.category_id, p.id, p.country, p.region_id, 'casual', 150, 'gps', '2027-06-28 00:00 Europe/Riga'::timestamptz, '2027-09-01 00:00 Europe/Riga'::timestamptz, 'published',
       jsonb_build_object(
         'lv', jsonb_build_object('title', 'Vasara: ' || coalesce(p.i18n->'lv'->>'name', p.name),
               'description', 'Apmeklē vasarā.' || ' ' || coalesce(p.i18n->'lv'->>'description', p.description) || ' Pietuvojies ' || p.radius_m || ' m attālumā, lai izpildītu.'),
         'ru', jsonb_build_object('title', 'Лето: ' || coalesce(p.i18n->'ru'->>'name', p.name),
               'description', 'Посетите летом.' || ' ' || coalesce(p.i18n->'ru'->>'description', p.description) || ' Подойдите ближе чем на ' || p.radius_m || ' м, чтобы выполнить.'))
FROM places p WHERE p.slug = 'jurmala-beach'
ON CONFLICT (slug) DO NOTHING;
INSERT INTO collection_items (collection_id, challenge_id, position)
SELECT c.id, ch.id, 1 FROM collections c, challenges ch WHERE c.slug = 'summer-2027' AND ch.slug = 'summer-2027-jurmala-beach'
ON CONFLICT DO NOTHING;
